contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address a1, address a2, bool flag) public payable {
        require(a1 != address(0) && a2 != address(0));
        // mismatched lengths must revert and leave state untouched
        address[] memory gs = new address[](2);
        gs[0] = a1;
        gs[1] = a2;
        bool[] memory fs = new bool[](1);
        fs[0] = flag;
        bool reverted;
        try c.setGoverned(gs, fs) { reverted = false; } catch { reverted = true; }
        // valid call with equal lengths must store the flags
        address[] memory gs2 = new address[](2);
        gs2[0] = a1;
        gs2[1] = a2;
        bool[] memory fs2 = new bool[](2);
        fs2[0] = flag;
        fs2[1] = !flag;
        c.setGoverned(gs2, fs2);
        assert(reverted && c.governed(a1) == flag && c.governed(a2) == !flag);
    }
    receive() external payable {}
}

