contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address newDao, address otherDao) public {
        require(newDao != address(0));
        require(otherDao != address(0));
        require(newDao != otherDao);
        require(address(c) != newDao);

        address daoBefore = c.DAO();
        address govBefore = c.governer();

        c.setDAO(newDao);

        address daoAfter = c.DAO();
        address govAfter = c.governer();

        c.setDAO(otherDao);
        address daoFinal = c.DAO();

        assert(
            daoAfter == newDao &&
            govAfter == address(0) &&
            daoFinal == otherDao &&
            daoBefore != newDao
        );
    }

    receive() external payable {}
}

