contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    fallback() external {
        if (msg.sig == bytes4(keccak256("configured()"))) {
            assembly {
                mstore(0, 1)
                return(0, 32)
            }
        }
        revert("unsupported");
    }

    receive() external payable {}

    function run(uint256 v) public payable {
        require(true);

        // enable enforcement for this (msg.sender == this) contract
        c.setEnforcement(true);

        // equal values must pass when enforcement is active
        bool revertedEqual;
        try c.enforceTolerance(v, v) {
            revertedEqual = false;
        } catch {
            revertedEqual = true;
        }

        // a change from 0 to 1 must fail with default changeTolerance == 0
        bool revertedChange;
        try c.enforceTolerance(0, 1) {
            revertedChange = false;
        } catch {
            revertedChange = true;
        }

        // once enforcement is disabled, the same change must pass
        c.setEnforcement(false);
        bool revertedAfterDisable;
        try c.enforceTolerance(0, 1) {
            revertedAfterDisable = false;
        } catch {
            revertedAfterDisable = true;
        }

        assert(!revertedEqual && revertedChange && !revertedAfterDisable);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(address newDao) public payable {
        require(true);

        // initially the contract is unconfigured
        require(!c.configured());

        // endConfiguration is a state-changing call: own top-level statement
        c.endConfiguration();

        // any non-DAO caller (this test) must no longer be able to change the DAO
        bool revertedSetDAO;
        try c.setDAO(newDao) {
            revertedSetDAO = false;
        } catch {
            revertedSetDAO = true;
        }

        assert(c.configured() && revertedSetDAO && c.DAO() != newDao);
    }
}

