contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint8 maxGovChange, uint256 epochSize, uint8 tolerance) public {
        // configured == false initially, so onlySuccessfulProposal passes for anyone.
        bool reverted;
        try c.configureSecurityParameters(maxGovChange, epochSize, tolerance) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            (uint256 es, , uint8 mg, uint8 tol) = c.security();
            assert(
                (reverted && tolerance >= 100) ||
                (!reverted && es == epochSize && mg == maxGovChange && tol == tolerance)
            );
        } else {
            assert(tolerance >= 100);
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Fresh C is not configured, so onlySuccessfulProposal passes for anyone.
    function run(uint8 t, uint256 v1, uint256 v2) public {
        require(t < 100);
        c.configureSecurityParameters(1, 1, t);
        c.setEnforcement(true);
        bool reverted;
        try c.enforceTolerance(v1, v2) { reverted = false; } catch { reverted = true; }
        bool expected;
        if (v1 > v2) {
            expected = (v2 == 0) ? (v1 > 1) : ((v1 - v2) * 100 >= uint256(t) * v1);
        } else {
            expected = (v1 == 0) ? (v2 > 1) : ((v2 - v1) * 100 >= uint256(t) * v1);
        }
        assert(reverted == expected);
    }

    // C.enforceTolerance calls Configurable(msg.sender).configured() on this test
    // contract; the fallback answers it with true so enforcement is active.
    fallback() external {
        assembly { mstore(0, 1) return(0, 32) }
    }
}

