contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    fallback() external {
        // mimic Configurable.configured() == false for calls routed back to this contract
        assembly {
            mstore(0, 0)
            return(0, 32)
        }
    }

    function run(uint256 v1, uint256 v2) public payable {
        require(true);
        // fresh deployment: enforceLimitsActive[address(this)] is false initially,
        // and this contract's configured() resolves to false via fallback.
        c.setEnforcement(false);
        bool ok1 = true;
        try c.enforceTolerance(v1, v2) {
            ok1 = true;
        } catch {
            ok1 = false;
        }
        bool ok2 = true;
        try c.enforceToleranceInt(int256(v1), int256(v2)) {
            ok2 = true;
        } catch {
            ok2 = false;
        }
        assert(ok1 && ok2);
    }

    receive() external payable {}
}

