contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address targetContract, address user, uint256 amount) public {
        // Ensure the pending decision exists with the given amount.
        c.setGoverned(new address[](0), new bool[](0));
        bool setupOk;
        try c.burnFlashGovernanceAsset(address(this), address(this), address(this), 0) {
            setupOk = true;
        } catch {
            setupOk = false;
        }
        require(setupOk);

        // Record the before-state (must be unset on a fresh contract).
        (uint256 amountBefore, , , ) = c.pendingFlashDecision(targetContract, user);
        require(amountBefore == 0);

        // burnFlashGovernanceAsset is callable when not configured and deletes the entry.
        c.burnFlashGovernanceAsset(targetContract, user, address(this), amount);

        (uint256 amountAfter, uint256 unlockAfter, address assetAfter, bool burnableAfter) = c.pendingFlashDecision(targetContract, user);

        assert(
            amountAfter == 0 &&
            unlockAfter == 0 &&
            assetAfter == address(0) &&
            burnableAfter == false
        );
    }

    fallback() external payable {}
    receive() external payable {}
}

