contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Answer 'configured()' (any selector) with true so that the Configurable
    // cast inside c.enforceTolerance succeeds and enforcement is active.
    fallback() external {
        assembly {
            mstore(0x00, 1)
            return(0x00, 0x20)
        }
    }

    function run(uint256 t, uint256 v1, uint256 v2) public {
        require(t < 100 && v1 < 2 ** 200 && v2 < 2 ** 200);

        // configure changeTolerance = t (allowed because c is unconfigured)
        c.configureSecurityParameters(1, 1, uint8(t));

        // Enforcement is currently OFF for this contract (msg.sender of setEnforcement)
        bool r1;
        try c.enforceTolerance(v1, v2) { r1 = false; } catch { r1 = true; }

        c.setEnforcement(true);

        bool r2;
        try c.enforceTolerance(v1, v2) { r2 = false; } catch { r2 = true; }

        bool expectRevert;
        if (v1 > v2) {
            if (v2 == 0) {
                expectRevert = v1 > 1;
            } else {
                expectRevert = ((v1 - v2) * 100) >= t * v1;
            }
        } else {
            if (v1 == 0) {
                expectRevert = v2 > 1;
            } else {
                expectRevert = ((v2 - v1) * 100) >= t * v1;
            }
        }

        assert(!r1 && r2 == expectRevert);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address target, address asset, bool flag) public {
        require(target != address(0));

        // Initially enforcement is inactive for the caller (this contract).
        bool before = c.enforceLimitsActive(address(this));

        // Withdrawing a governance asset when no flash decision is pending must revert.
        bool wReverted;
        bool ok = false;
        // need top-level statement, so wrap: cannot use try nested; do plain try at top level below
        // (kept flat: try/catch at statement level is allowed)
        bool w;
        if (!ok) {
            try c.withdrawGovernanceAsset(target, asset) { w = false; } catch { w = true; }
            wReverted = w;
        }

        c.setEnforcement(flag);
        bool after = c.enforceLimitsActive(address(this));

        assert(!before && wReverted && after == flag);
    }
}

