        require(true);
        // burning a flash-governance asset for an arbitrary target/user on an
        // unconfigured contract must always succeed (configured == false, so the
        // onlySuccessfulProposal check passes) and must delete the pending decision
        (, , , bool burnableBefore) = c.pendingFlashDecision(target, user);
        c.burnFlashGovernanceAsset(target, user, asset, amount);
        (address a, uint256 amt, uint256 unlockTime, bool burnableAfter) = c.pendingFlashDecision(target, user);
        assert(a == address(0) && amt == 0 && unlockTime == 0 && burnableAfter == false && burnableBefore == burnableAfter);
    }

    receive() external payable {}
}

