contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, address target) public {
        require(target != address(0));
        require(amount > 0);

        address[] memory governables = new address[](1);
        governables[0] = address(this);
        bool[] memory flags = new bool[](1);
        flags[0] = true;
        c.setGoverned(governables, flags);

        c.configureFlashGovernance(address(this), amount, 0, false);
        c.assertGovernanceApproved(address(this), target, false);

        (uint256 amt0, uint256 unlock0, address asset0, bool burnable0) = c.pendingFlashDecision(target, address(this));
        assert(amt0 == amount && asset0 == address(this) && !burnable0);

        c.burnFlashGovernanceAsset(target, address(this), address(this), amount);

        (uint256 amt1, uint256 unlock1, address asset1, bool burnable1) = c.pendingFlashDecision(target, address(this));
        assert(amt1 == 0 && unlock1 == 0 && asset1 == address(0) && !burnable1);

        bool reverted;
        try c.withdrawGovernanceAsset(target, address(this)) { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }

    fallback(bytes calldata) external payable returns (bytes memory) {
        // return true for ERC20 transferFrom/transfer selectors
        return abi.encode(true);
    }

    receive() external payable {}
}

