contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Responds to Configurable(msg.sender).configured() called on this contract by c.
    fallback(bytes calldata input) external returns (bytes memory) {
        if (input.length == 4) return abi.encode(true);
        return "";
    }

    function run(uint256 v1, uint256 v2) public payable {
        // Enforcement is off by default: even a far-out-of-tolerance change must not revert.
        bool rOff;
        try c.enforceTolerance(v1, v2) { rOff = false; } catch { rOff = true; }

        // Caller enables enforcement.
        c.setEnforcement(true);

        // With enforcement on, the tolerance check applies: (2,0) is a change of 2 vs 0
        // and must revert regardless of the parameters used above.
        bool rOnFar;
        try c.enforceTolerance(2, 0) { rOnFar = false; } catch { rOnFar = true; }

        // A change within tolerance (identical values) must not revert.
        bool rOnNear;
        try c.enforceTolerance(3, 3) { rOnNear = false; } catch { rOnNear = true; }

        // Caller disables enforcement again: far change must revert no longer.
        c.setEnforcement(false);

        bool rOffAgain;
        try c.enforceTolerance(v1, v2) { rOffAgain = false; } catch { rOffAgain = true; }

        assert(!rOff && rOnFar && !rOnNear && !rOffAgain);
    }

    receive() external payable {}
}

