    constructor(C _c) { c = _c; }

    function run(address target, address asset) public payable {
        // No flash decision has ever been made: withdrawal must revert for any
        // target/asset, since pendingFlashDecision is empty (amount == 0).
        bool wReverted;
        try c.withdrawGovernanceAsset(target, asset) { wReverted = false; } catch { wReverted = true; }

