        // asset configured cannot succeed: it must revert and must not create
        // a pending decision.
        bool aReverted;
        try c.assertGovernanceApproved(address(this), target, false) { aReverted = false; } catch { aReverted = true; }

        (, uint256 recordedAmount, , ) = c.pendingFlashDecision(target, address(this));

        assert(wReverted && aReverted && recordedAmount == 0);
    }

    receive() external payable {}
}

