contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint8 maxGovChange, uint256 epochSize, uint8 tolerance) public {
        // The contract rejects a tolerance of 100 or more.
        require(tolerance < 100);

        uint8 maxGovBefore;
        uint256 epochBefore;
        uint8 tolBefore;
        (maxGovBefore, epochBefore, tolBefore) = c.security();

        c.configureSecurityParameters(maxGovChange, epochSize, tolerance);

        (uint8 maxGovAfter, uint256 epochAfter, uint8 tolAfter) = c.security();

        assert(
            maxGovBefore != maxGovChange &&
            maxGovAfter == maxGovChange &&
            epochBefore != epochSize &&
            epochAfter == epochSize &&
            tolBefore != tolerance &&
            tolAfter == tolerance
        );
    }
}

